131→        assert_eq!(blob[0], 0x02);
132→        assert_eq!(blob[1], 0x00); // 129 >> 8 = 0
133→        assert_eq!(blob[2], 0x81); // 129 & 0xFF = 0x81
134→        assert_eq!(&blob[3..132], key.as_slice());
135→        assert_eq!(&blob[132..], b"meta");
136→    }
137→
138→    // Cross-platform test vector: MUST match TypeScript vault-blob-vectors.test.ts
139→    // Key (129 bytes): 0xAA followed by 128 bytes incrementing 0x00..0x7F
140→    // Metadata: UTF-8 of '{"iv":"abc","data":"def"}'
141→    // Expected hex: 02 0081 aa 0001...7f 7b226976...7d
142→    #[test]
143→    fn test_cross_platform_vector() {
144→        // Build the same 129-byte key as TypeScript test vector
145→        let mut key = vec![0xAA];
146→        for i in 0u8..128 {
147→            key.push(i);
148→        }
149→        assert_eq!(key.len(), 129);
150→
151→        let metadata = b"{\"iv\":\"abc\",\"data\":\"def\"}";
152→        let blob = serialize_vault_blob_v2(&key, metadata).unwrap();
153→
154→        // Verify structure
155→        assert_eq!(blob[0], 0x02);
156→        assert_eq!(blob[1], 0x00);
157→        assert_eq!(blob[2], 0x81); // 129
158→        assert_eq!(blob.len(), 3 + 129 + metadata.len());
159→
160→        // Verify exact hex matches TypeScript EXPECTED_HEX
161→        let blob_hex = hex::encode(&blob);
162→        let expected_hex = concat!(
163→            "02",   // version byte
164→            "0081", // key_len = 129
165→            "aa",   // key[0]
166→            "000102030405060708090a0b0c0d0e0f", // key[1..16]
167→            "101112131415161718191a1b1c1d1e1f", // key[17..32]
168→            "202122232425262728292a2b2c2d2e2f", // key[33..48]
169→            "303132333435363738393a3b3c3d3e3f", // key[49..64]
170→            "404142434445464748494a4b4c4d4e4f", // key[65..80]
171→            "505152535455565758595a5b5c5d5e5f", // key[81..96]
172→            "606162636465666768696a6b6c6d6e6f", // key[97..112]
173→            "707172737475767778797a7b7c7d7e7f", // key[113..128]
174→            "7b226976223a22616263222c2264617461223a22646566227d", // metadata JSON
175→        );
176→        assert_eq!(blob_hex, expected_hex);
177→
178→        // Round-trip
179→        let (dk, dm) = deserialize_vault_blob_v2(&blob).unwrap();
180→        assert_eq!(dk, key.as_slice());
181→        assert_eq!(dm, metadata);
182→    }
