  1→//! Request and response types for the CipherBox backend API.
  2→//!
  3→//! All structs use camelCase serialization to match the API's JSON format.
  4→//! Auth DTOs use manual Debug impls to redact sensitive fields (M-11).
  5→
  6→use std::fmt;
  7→
  8→use serde::{Deserialize, Serialize};
  9→
 10→/// Login request body sent to POST /auth/login.
 11→#[derive(Serialize)]
 12→#[serde(rename_all = "camelCase")]
 13→pub struct LoginRequest {
 14→    pub id_token: String,
 15→    pub public_key: String,
 16→    pub login_type: String,
 17→}
