  1→//! Background sync daemon for CipherBox Desktop.
  2→//!
  3→//! Polls IPNS every 30 seconds for metadata changes, refreshes the inode table
  4→//! when changes are detected, and processes queued offline writes.
  5→//!
  6→//! Uses sequence number comparison (not CID) per project decision from Phase 7.
  7→
  8→pub mod queue;
  9→#[cfg(test)]
 10→mod tests;
 11→
 12→pub use queue::{QueuedWrite, UploadHandler, WriteQueue};
 13→
 14→use std::collections::HashMap;
 15→use std::sync::Arc;
 16→use std::time::Duration;
 17→
 18→use tokio::sync::mpsc;
 19→use tokio::sync::RwLock;
 20→
 21→/// Default polling interval for IPNS sync (30 seconds).
 22→pub const SYNC_INTERVAL: Duration = Duration::from_secs(30);
 23→
 24→/// The background sync daemon.
 25→///
 26→/// Runs in a tokio task, polling IPNS for metadata changes at a regular interval.
 27→/// Can be triggered manually via the `sync_now_tx` channel from the tray menu.
 28→pub struct SyncDaemon {
 29→    /// API client for IPFS/IPNS operations.
 30→    api: Arc<crate::api::client::ApiClient>,
 31→    /// Root folder IPNS name (shared reference, updated on auth).
 32→    root_ipns_name: Arc<RwLock<Option<String>>>,
 33→    /// Whether the user is fully authenticated (shared reference).
 34→    is_authenticated: Arc<RwLock<bool>>,
 35→    /// Poll interval (default 30s).
 36→    poll_interval: Duration,
 37→    /// Cached IPNS sequence numbers: ipns_name -> last known sequence_number.
 38→    cached_sequence_numbers: HashMap<String, u64>,
 39→    /// Channel receiver for manual sync triggers (from tray "Sync Now" button).
 40→    sync_now_rx: mpsc::Receiver<()>,
 41→    /// Offline write queue for deferred uploads.
 42→    write_queue: WriteQueue,
 43→    /// AppHandle for updating tray status.
 44→    app_handle: tauri::AppHandle,
 45→    /// Whether the last poll attempt detected offline state.
 46→    was_offline: bool,
 47→}
 48→
 49→impl SyncDaemon {
 50→    /// Create a new sync daemon.
 51→    ///
 52→    /// The `sync_now_rx` channel receives manual sync triggers from the tray menu.
 53→    /// Shared references to `root_ipns_name` and `is_authenticated` are read from
 54→    /// AppState fields (they are `tokio::sync::RwLock` wrapped in Arc by the caller).
 55→    pub fn new(
 56→        api: Arc<crate::api::client::ApiClient>,
 57→        root_ipns_name: Arc<RwLock<Option<String>>>,
 58→        is_authenticated: Arc<RwLock<bool>>,
 59→        sync_now_rx: mpsc::Receiver<()>,
 60→        app_handle: tauri::AppHandle,
 61→    ) -> Self {
 62→        Self {
 63→            api,
 64→            root_ipns_name,
 65→            is_authenticated,
 66→            poll_interval: SYNC_INTERVAL,
 67→            cached_sequence_numbers: HashMap::new(),
 68→            sync_now_rx,
 69→            write_queue: WriteQueue::default(),
 70→            app_handle,
 71→            was_offline: false,
 72→        }
 73→    }
 74→
 75→    /// Main run loop. Call from a spawned tokio task.
 76→    ///
 77→    /// Uses `tokio::select!` to wait on either the periodic tick or a manual trigger.
 78→    /// On each tick: poll IPNS for changes, process write queue.
 79→    pub async fn run(&mut self) {
 80→        let mut ticker = tokio::time::interval(self.poll_interval);
 81→        // The first tick fires immediately; skip it to let the app finish mounting.
 82→        ticker.tick().await;
 83→
 84→        log::info!(
 85→            "Sync daemon started (interval: {}s)",
 86→            self.poll_interval.as_secs()
 87→        );
 88→
 89→        loop {
 90→            tokio::select! {
 91→                _ = ticker.tick() => {
 92→                    self.sync_cycle().await;
 93→                }
 94→                Some(()) = self.sync_now_rx.recv() => {
 95→                    log::info!("Manual sync triggered");
 96→                    self.sync_cycle().await;
 97→                }
 98→            }
 99→        }
100→    }
101→
102→    /// Execute one full sync cycle: poll + process write queue.
103→    async fn sync_cycle(&mut self) {
104→        // Check if authenticated
105→        if !*self.is_authenticated.read().await {
106→            return;
107→        }
108→
109→        // Update tray to Syncing
110→        let _ = crate::tray::update_tray_status(
111→            &self.app_handle,
112→            &crate::tray::TrayStatus::Syncing,
113→        );
114→
115→        match self.poll().await {
116→            Ok(()) => {
117→                // Transitioned from offline to online
118→                if self.was_offline {
119→                    log::info!("Connectivity restored, resuming sync");
120→                    self.was_offline = false;
121→                }
122→
123→                // Process queued writes (best-effort)
124→                if !self.write_queue.is_empty() {
125→                    log::info!(
126→                        "Processing {} queued writes",
127→                        self.write_queue.len()
128→                    );
129→                    // Write queue processing requires an UploadHandler implementation
130→                    // which would use self.api. For v1, log pending items.
131→                    // Full write queue processing with FUSE integration is deferred
132→                    // to after the UploadHandler trait is wired to the ApiClient+FUSE layer.
133→                    log::debug!(
134→                        "Write queue has {} pending items",
135→                        self.write_queue.len()
136→                    );
137→                }
138→
139→                let _ = crate::tray::update_tray_status(
140→                    &self.app_handle,
141→                    &crate::tray::TrayStatus::Synced,
142→                );
143→            }
144→            Err(e) => {
145→                log::warn!("Sync poll failed: {}", e);
146→
147→                // Determine if this is a network error (offline) or API error
148→                if is_network_error(&e) {
149→                    if !self.was_offline {
150→                        log::info!("Network appears offline, pausing active sync");
151→                        self.was_offline = true;
152→                    }
153→                    let _ = crate::tray::update_tray_status(
154→                        &self.app_handle,
155→                        &crate::tray::TrayStatus::Offline,
156→                    );
157→                } else {
158→                    let _ = crate::tray::update_tray_status(
159→                        &self.app_handle,
160→                        &crate::tray::TrayStatus::Error(sanitize_error(&e)),
161→                    );
162→                }
163→            }
164→        }
165→    }
166→
167→    /// Poll IPNS for all known folders and detect changes via sequence number comparison.
168→    ///
169→    /// For each folder:
170→    /// 1. Resolve IPNS name to get current sequence number
171→    /// 2. Compare with cached sequence number
172→    /// 3. If changed: log the change (metadata cache TTL handles refresh on next FUSE access)
173→    /// 4. Update cached sequence numbers
174→    async fn poll(&mut self) -> Result<(), String> {
175→        // Get root IPNS name
176→        let root_ipns_name = self
177→            .root_ipns_name
178→            .read()
179→            .await
180→            .clone()
181→            .ok_or_else(|| "Root IPNS name not available".to_string())?;
182→
183→        // Resolve root folder IPNS
184→        let resolve_result =
185→            crate::api::ipns::resolve_ipns(&self.api, &root_ipns_name).await?;
186→
187→        let new_seq = resolve_result
188→            .sequence_number
189→            .parse::<u64>()
190→            .unwrap_or(0);
191→
192→        let cached_seq = self
193→            .cached_sequence_numbers
194→            .get(&root_ipns_name)
195→            .copied()
196→            .unwrap_or(0);
197→
198→        if new_seq != cached_seq {
199→            log::info!(
200→                "IPNS change detected for root folder: seq {} -> {}",
201→                cached_seq,
202→                new_seq
203→            );
204→            self.cached_sequence_numbers
205→                .insert(root_ipns_name.clone(), new_seq);
206→
207→            // The metadata cache has a 30s TTL, so the next FUSE readdir/lookup
208→            // will fetch and decrypt fresh metadata automatically.
209→            log::info!(
210→                "Root folder metadata changed (CID: {}). Cache will refresh on next access.",
211→                resolve_result.cid
212→            );
213→        }
214→
215→        Ok(())
216→    }
217→
218→    /// Access the write queue for enqueuing offline writes.
219→    pub fn write_queue_mut(&mut self) -> &mut WriteQueue {
220→        &mut self.write_queue
221→    }
222→}
223→
224→/// Sanitize error messages before displaying in tray status or notifications.
225→///
226→/// Removes sensitive information that could leak implementation details:
227→/// - Truncates after first newline or at 80 chars (strips API response bodies)
228→/// - Replaces internal filesystem paths with `[path]`
229→/// - Replaces long hex strings (>40 chars) that may be tokens with `[token]`
230→fn sanitize_error(error: &str) -> String {
231→    // Truncate at first newline or 80 chars, whichever is shorter
232→    let truncated = error
233→        .split('\n')
234→        .next()
235→        .unwrap_or(error);
236→    let truncated = if truncated.len() > 80 {
237→        // Find the last char boundary at or before byte 80
238→        let mut boundary = 80;
239→        while boundary > 0 && !truncated.is_char_boundary(boundary) {
240→            boundary -= 1;
241→        }
242→        format!("{}...", &truncated[..boundary])
243→    } else {
244→        truncated.to_string()
245→    };
246→
247→    // Remove internal filesystem paths
248→    let sanitized = regex_replace_paths(&truncated);
249→
250→    // Remove token-like hex strings (>40 hex chars)
251→    regex_replace_tokens(&sanitized)
252→}
253→
254→/// Replace filesystem paths like /Users/... or /home/... with [path].
255→fn regex_replace_paths(input: &str) -> String {
256→    let mut result = String::with_capacity(input.len());
257→    let mut chars = input.char_indices().peekable();
258→
259→    while let Some((i, c)) = chars.next() {
260→        if c == '/' && (input[i..].starts_with("/Users/") || input[i..].starts_with("/home/")) {
261→            result.push_str("[path]");
262→            // Skip until whitespace or end
263→            while let Some(&(_, next_c)) = chars.peek() {
264→                if next_c.is_whitespace() || next_c == '"' || next_c == '\'' {
265→                    break;
266→                }
267→                chars.next();
268→            }
269→        } else {
270→            result.push(c);
271→        }
272→    }
273→    result
274→}
275→
276→/// Replace long hex strings (>40 chars) with [token].
277→fn regex_replace_tokens(input: &str) -> String {
278→    let mut result = String::with_capacity(input.len());
279→    let mut hex_run = String::new();
280→
281→    for c in input.chars() {
282→        if c.is_ascii_hexdigit() {
283→            hex_run.push(c);
284→        } else {
285→            if hex_run.len() > 40 {
286→                result.push_str("[token]");
287→            } else {
288→                result.push_str(&hex_run);
289→            }
290→            hex_run.clear();
291→            result.push(c);
292→        }
293→    }
294→
295→    // Flush trailing hex run
296→    if hex_run.len() > 40 {
297→        result.push_str("[token]");
298→    } else {
299→        result.push_str(&hex_run);
300→    }
301→
302→    result
303→}
304→
305→/// Heuristic check for network-level errors vs application errors.
306→fn is_network_error(error: &str) -> bool {
307→    let network_patterns = [
308→        "dns error",
309→        "connect error",
310→        "connection refused",
311→        "network unreachable",
312→        "timed out",
313→        "timeout",
314→        "no route to host",
315→        "network is down",
316→        "couldn't resolve host",
317→    ];
318→    let lower = error.to_lowercase();
319→    network_patterns.iter().any(|p| lower.contains(p))
320→}
