  1→//! IPNS record creation, marshaling, and name derivation.
  2→//!
  3→//! Produces IPNS records compatible with the TypeScript `ipns` npm package output.
  4→//! - CBOR-encoded data field with V2 signature
  5→//! - Protobuf-encoded IpnsEntry for marshaling
  6→//! - CIDv1 base36 IPNS name derivation
  7→
  8→use std::time::{Duration, SystemTime, UNIX_EPOCH};
  9→
 10→use ciborium::Value as CborValue;
 11→use thiserror::Error;
 12→
 13→use super::ed25519::{get_public_key, sign_ed25519};
 14→
 15→/// IPNS signature prefix per IPFS spec: "ipns-signature:".
 16→const IPNS_SIGNATURE_PREFIX: &[u8] = b"ipns-signature:";
 17→
 18→/// Default IPNS record TTL: 300 seconds (5 minutes) in nanoseconds.
 19→/// This matches the ipns npm package default.
 20→const DEFAULT_TTL_NS: u64 = 300_000_000_000;
 21→
 22→#[derive(Debug, Error)]
 23→pub enum IpnsError {
 24→    #[error("IPNS record creation failed")]
 25→    CreationFailed,
 26→    #[error("IPNS record marshaling failed")]
 27→    MarshalingFailed,
 28→    #[error("IPNS name derivation failed")]
 29→    DerivationFailed,
 30→    #[error("Invalid private key")]
 31→    InvalidPrivateKey,
 32→    #[error("Invalid public key")]
 33→    InvalidPublicKey,
 34→    #[error("CBOR encoding failed")]
 35→    CborEncodingFailed,
 36→    #[error("Signing failed")]
 37→    SigningFailed,
 38→}
 39→
 40→/// IPNS record structure matching the TypeScript IPNSRecord type.
 41→#[derive(Debug, Clone)]
 42→pub struct IpnsRecord {
 43→    /// IPFS path value (e.g., "/ipfs/bafy...").
 44→    pub value: String,
 45→    /// RFC3339 validity timestamp with nanosecond precision.
 46→    pub validity: String,
 47→    /// Validity type (0 = EOL).
 48→    pub validity_type: u32,
 49→    /// Monotonically increasing sequence number.
 50→    pub sequence: u64,
 51→    /// TTL in nanoseconds.
 52→    pub ttl: u64,
 53→    /// 64-byte Ed25519 V1 signature.
 54→    pub signature_v1: Vec<u8>,
 55→    /// 64-byte Ed25519 V2 signature.
 56→    pub signature_v2: Vec<u8>,
 57→    /// CBOR-encoded record data.
 58→    pub data: Vec<u8>,
 59→    /// 32-byte Ed25519 public key.
 60→    pub public_key: Vec<u8>,
 61→}
 62→
 63→/// Build the CBOR-encoded data field for an IPNS record.
 64→///
 65→/// The field order matches the ipns npm package: TTL, Value, Sequence, Validity, ValidityType.
 66→/// Keys are strings, values match the types used by the ipns package.
 67→fn build_cbor_data(
 68→    value: &str,
 69→    validity: &str,
 70→    sequence: u64,
 71→    ttl: u64,
 72→) -> Result<Vec<u8>, IpnsError> {
 73→    // The ipns npm package uses a CBOR map with string keys.
 74→    // Field order (matching ipns npm package output): TTL, Value, Sequence, Validity, ValidityType
 75→    //
 76→    // - TTL: unsigned integer (nanoseconds)
 77→    // - Value: byte string (the IPFS path as bytes)
 78→    // - Sequence: unsigned integer
 79→    // - Validity: byte string (RFC3339 timestamp as bytes)
 80→    // - ValidityType: unsigned integer (0 = EOL)
 81→    let cbor_map = CborValue::Map(vec![
 82→        (
 83→            CborValue::Text("TTL".to_string()),
 84→            CborValue::Integer(ttl.into()),
 85→        ),
 86→        (
 87→            CborValue::Text("Value".to_string()),
 88→            CborValue::Bytes(value.as_bytes().to_vec()),
 89→        ),
 90→        (
 91→            CborValue::Text("Sequence".to_string()),
 92→            CborValue::Integer(sequence.into()),
 93→        ),
 94→        (
 95→            CborValue::Text("Validity".to_string()),
 96→            CborValue::Bytes(validity.as_bytes().to_vec()),
 97→        ),
 98→        (
 99→            CborValue::Text("ValidityType".to_string()),
100→            CborValue::Integer(0.into()),
101→        ),
102→    ]);
103→
104→    let mut buf = Vec::new();
105→    ciborium::into_writer(&cbor_map, &mut buf).map_err(|_| IpnsError::CborEncodingFailed)?;
106→    Ok(buf)
107→}
108→
109→/// Format a timestamp as RFC3339 with nanosecond precision matching the ipns npm package.
110→///
111→/// The ipns package uses format: "2026-02-08T23:31:12.138000000Z"
112→/// This is: full datetime + "." + 9-digit nanoseconds + "Z"
113→fn format_validity_timestamp(validity_time: SystemTime) -> String {
114→    let duration = validity_time
115→        .duration_since(UNIX_EPOCH)
116→        .unwrap_or(Duration::ZERO);
117→    let secs = duration.as_secs();
118→    let nanos = duration.subsec_nanos();
119→
120→    // Compute date/time components from Unix timestamp
121→    let days = secs / 86400;
122→    let time_of_day = secs % 86400;
123→    let hours = time_of_day / 3600;
124→    let minutes = (time_of_day % 3600) / 60;
125→    let seconds = time_of_day % 60;
126→
127→    // Convert days since epoch to date using civil_from_days algorithm
128→    let (year, month, day) = civil_from_days(days as i64);
129→
130→    format!(
131→        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:09}Z",
132→        year, month, day, hours, minutes, seconds, nanos
133→    )
134→}
135→
136→/// Convert days since Unix epoch to (year, month, day).
137→/// Algorithm from Howard Hinnant's civil_from_days.
138→fn civil_from_days(days: i64) -> (i64, u32, u32) {
139→    let z = days + 719468;
140→    let era = if z >= 0 { z } else { z - 146096 } / 146097;
141→    let doe = (z - era * 146097) as u64; // day of era [0, 146096]
142→    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; // year of era [0, 399]
143→    let y = (yoe as i64) + era * 400;
144→    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // day of year [0, 365]
145→    let mp = (5 * doy + 2) / 153; // [0, 11]
146→    let d = doy - (153 * mp + 2) / 5 + 1; // day [1, 31]
147→    let m = if mp < 10 { mp + 3 } else { mp - 9 }; // month [1, 12]
148→    let y = if m <= 2 { y + 1 } else { y };
149→    (y, m as u32, d as u32)
150→}
151→
152→/// Compute the V1 signature.
153→///
154→/// Per IPNS spec, V1 signature is over: value_bytes + validity_bytes + varint(validityType)
155→fn compute_v1_signature(
156→    ed25519_private_key: &[u8; 32],
157→    value: &str,
158→    validity: &str,
159→) -> Result<Vec<u8>, IpnsError> {
160→    let mut data_to_sign = Vec::new();
161→    data_to_sign.extend_from_slice(value.as_bytes());
162→    data_to_sign.extend_from_slice(validity.as_bytes());
163→    // ValidityType 0 as varint = single byte 0x00
164→    data_to_sign.push(0x00);
165→
166→    sign_ed25519(&data_to_sign, ed25519_private_key).map_err(|_| IpnsError::SigningFailed)
167→}
168→
169→/// Compute the V2 signature.
170→///
171→/// Per IPNS spec, V2 signature is over: "ipns-signature:" + cbor_data
172→fn compute_v2_signature(
173→    ed25519_private_key: &[u8; 32],
174→    cbor_data: &[u8],
175→) -> Result<Vec<u8>, IpnsError> {
176→    let mut data_to_sign = Vec::with_capacity(IPNS_SIGNATURE_PREFIX.len() + cbor_data.len());
177→    data_to_sign.extend_from_slice(IPNS_SIGNATURE_PREFIX);
178→    data_to_sign.extend_from_slice(cbor_data);
179→
180→    sign_ed25519(&data_to_sign, ed25519_private_key).map_err(|_| IpnsError::SigningFailed)
181→}
182→
183→/// Create an IPNS record signed with the given Ed25519 private key.
184→///
185→/// Matches the TypeScript `createIpnsRecord` with `v1Compatible: true`.
186→pub fn create_ipns_record(
187→    ed25519_private_key: &[u8; 32],
188→    value: &str,
189→    sequence_number: u64,
190→    lifetime_ms: u64,
191→) -> Result<IpnsRecord, IpnsError> {
192→    // Derive public key
193→    let public_key = get_public_key(ed25519_private_key).map_err(|_| IpnsError::InvalidPrivateKey)?;
194→
195→    // Compute validity timestamp
196→    let now = SystemTime::now();
197→    let lifetime_duration = Duration::from_millis(lifetime_ms);
198→    let validity_time = now + lifetime_duration;
199→    let validity = format_validity_timestamp(validity_time);
200→
201→    let ttl = DEFAULT_TTL_NS;
202→
203→    // Build CBOR data
204→    let cbor_data = build_cbor_data(value, &validity, sequence_number, ttl)?;
205→
206→    // Compute V2 signature (over "ipns-signature:" + cbor_data)
207→    let signature_v2 = compute_v2_signature(ed25519_private_key, &cbor_data)?;
208→
209→    // Compute V1 signature (over value + validity + varint(0))
210→    let signature_v1 = compute_v1_signature(ed25519_private_key, value, &validity)?;
211→
212→    Ok(IpnsRecord {
213→        value: value.to_string(),
214→        validity,
215→        validity_type: 0,
216→        sequence: sequence_number,
217→        ttl,
218→        signature_v1,
219→        signature_v2,
220→        data: cbor_data,
221→        public_key,
222→    })
223→}
224→
225→/// Encode the Ed25519 public key in libp2p PublicKey protobuf format.
226→///
227→/// message PublicKey { KeyType Type = 1; bytes Data = 2; }
228→/// where KeyType.Ed25519 = 1
229→fn encode_libp2p_public_key(ed25519_public_key: &[u8]) -> Vec<u8> {
230→    let mut buf = Vec::new();
231→    // Field 1 (Type): varint, field_number=1, wire_type=0 => tag = 0x08
232→    buf.push(0x08);
233→    // Value: 1 (Ed25519)
234→    buf.push(0x01);
235→    // Field 2 (Data): length-delimited, field_number=2, wire_type=2 => tag = 0x12
236→    buf.push(0x12);
237→    // Length of public key (32 bytes)
238→    buf.push(ed25519_public_key.len() as u8);
239→    buf.extend_from_slice(ed25519_public_key);
240→    buf
241→}
242→
243→/// Marshal an IPNS record to protobuf bytes.
244→///
245→/// IpnsEntry protobuf fields:
246→/// - field 1 (bytes): Value
247→/// - field 2 (bytes): signatureV1
248→/// - field 3 (enum): ValidityType (0 = EOL)
249→/// - field 4 (bytes): Validity (RFC3339 as bytes)
250→/// - field 5 (uint64): Sequence
251→/// - field 6 (uint64): TTL (nanoseconds)
252→/// - field 7 (bytes): pubKey (libp2p protobuf-wrapped Ed25519 public key)
253→/// - field 8 (bytes): signatureV2
254→/// - field 9 (bytes): data (CBOR)
255→pub fn marshal_ipns_record(record: &IpnsRecord) -> Result<Vec<u8>, IpnsError> {
256→    let mut buf = Vec::new();
257→
258→    // Field 1: Value (bytes, tag = 0x0a)
259→    encode_proto_bytes(&mut buf, 1, record.value.as_bytes());
260→
261→    // Field 2: signatureV1 (bytes, tag = 0x12)
262→    encode_proto_bytes(&mut buf, 2, &record.signature_v1);
263→
264→    // Field 3: ValidityType (enum/varint, tag = 0x18)
265→    encode_proto_varint(&mut buf, 3, record.validity_type as u64);
266→
267→    // Field 4: Validity (bytes, tag = 0x22)
268→    encode_proto_bytes(&mut buf, 4, record.validity.as_bytes());
269→
270→    // Field 5: Sequence (uint64, tag = 0x28)
271→    encode_proto_varint(&mut buf, 5, record.sequence);
272→
273→    // Field 6: TTL (uint64, tag = 0x30)
274→    encode_proto_varint(&mut buf, 6, record.ttl);
275→
276→    // Field 7: pubKey (bytes, tag = 0x3a) -- libp2p PublicKey protobuf
277→    let libp2p_pub_key = encode_libp2p_public_key(&record.public_key);
278→    encode_proto_bytes(&mut buf, 7, &libp2p_pub_key);
279→
280→    // Field 8: signatureV2 (bytes, tag = 0x42)
281→    encode_proto_bytes(&mut buf, 8, &record.signature_v2);
282→
283→    // Field 9: data (bytes, tag = 0x4a) -- CBOR
284→    encode_proto_bytes(&mut buf, 9, &record.data);
285→
286→    Ok(buf)
287→}
288→
289→/// Encode a protobuf length-delimited (bytes) field.
290→fn encode_proto_bytes(buf: &mut Vec<u8>, field_number: u32, data: &[u8]) {
291→    // Tag: (field_number << 3) | 2 (wire_type = length-delimited)
292→    encode_varint(buf, ((field_number as u64) << 3) | 2);
293→    // Length
294→    encode_varint(buf, data.len() as u64);
295→    // Data
296→    buf.extend_from_slice(data);
297→}
298→
299→/// Encode a protobuf varint field.
300→fn encode_proto_varint(buf: &mut Vec<u8>, field_number: u32, value: u64) {
301→    // Tag: (field_number << 3) | 0 (wire_type = varint)
302→    encode_varint(buf, ((field_number as u64) << 3) | 0);
303→    // Value
304→    encode_varint(buf, value);
305→}
306→
307→/// Encode a varint (protobuf LEB128).
308→fn encode_varint(buf: &mut Vec<u8>, mut value: u64) {
309→    loop {
310→        let byte = (value & 0x7f) as u8;
311→        value >>= 7;
312→        if value == 0 {
313→            buf.push(byte);
314→            break;
315→        } else {
316→            buf.push(byte | 0x80);
317→        }
318→    }
319→}
320→
321→/// Derive the IPNS name (CIDv1 base36) from an Ed25519 public key.
322→///
323→/// Steps:
324→/// 1. Wrap public key in libp2p PublicKey protobuf
325→/// 2. Create identity multihash: 0x00 (identity) + varint(len) + data
326→/// 3. Create CIDv1: version=1, codec=0x72 (libp2p-key), multihash
327→/// 4. Encode as base36 (k... prefix)
328→pub fn derive_ipns_name(ed25519_public_key: &[u8; 32]) -> Result<String, IpnsError> {
329→    // Step 1: Wrap in libp2p PublicKey protobuf
330→    let libp2p_pub_key = encode_libp2p_public_key(ed25519_public_key);
331→
332→    // Step 2: Create identity multihash
333→    // Identity multihash: code=0x00, length=varint(data.len()), data
334→    let mut identity_multihash = Vec::new();
335→    identity_multihash.push(0x00); // identity hash function code
336→    // Encode length as unsigned varint
337→    encode_unsigned_varint(&mut identity_multihash, libp2p_pub_key.len() as u64);
338→    identity_multihash.extend_from_slice(&libp2p_pub_key);
339→
340→    // Step 3: Create CIDv1
341→    // CIDv1 binary: version(1) + codec(0x72, libp2p-key) + multihash
342→    let mut cid_bytes = Vec::new();
343→    encode_unsigned_varint(&mut cid_bytes, 1); // CID version 1
344→    encode_unsigned_varint(&mut cid_bytes, 0x72); // libp2p-key codec
345→    cid_bytes.extend_from_slice(&identity_multihash);
346→
347→    // Step 4: Encode as base36 with 'k' prefix
348→    let base36 = encode_base36(&cid_bytes);
349→    Ok(format!("k{}", base36))
350→}
351→
352→/// Encode unsigned varint (same as protobuf varint / LEB128).
353→fn encode_unsigned_varint(buf: &mut Vec<u8>, mut value: u64) {
354→    loop {
355→        let byte = (value & 0x7f) as u8;
356→        value >>= 7;
357→        if value == 0 {
358→            buf.push(byte);
359→            break;
360→        } else {
361→            buf.push(byte | 0x80);
362→        }
363→    }
364→}
365→
366→/// Encode bytes as base36 (lowercase).
367→///
368→/// Base36 alphabet: REDACTED
369→fn encode_base36(data: &[u8]) -> String {
370→    if data.is_empty() {
371→        return String::new();
372→    }
373→
374→    const ALPHABET: &[u8; 36] = b"REDACTED";
375→
376→    // Count leading zeros
377→    let leading_zeros = data.iter().take_while(|&&b| b == 0).count();
378→
379→    // Convert byte array to big integer using repeated division
380→    let mut num = data.to_vec();
381→    let mut result = Vec::new();
382→
383→    while !num.is_empty() {
384→        let mut remainder: u32 = 0;
385→        let mut quotient = Vec::new();
386→
387→        for &byte in &num {
388→            let acc = (remainder << 8) | (byte as u32);
389→            let digit = acc / 36;
390→            remainder = acc % 36;
391→
392→            if !quotient.is_empty() || digit > 0 {
393→                quotient.push(digit as u8);
394→            }
395→        }
396→
397→        result.push(ALPHABET[remainder as usize]);
398→        num = quotient;
399→    }
400→
401→    // Add leading '0's for each leading zero byte
402→    for _ in 0..leading_zeros {
403→        result.push(b'0');
404→    }
405→
406→    result.reverse();
407→    String::from_utf8(result).unwrap_or_default()
408→}
