  1→//! AES-256-CTR encryption/decryption.
  2→//!
  3→//! Symmetric encryption for media file content using CTR mode.
  4→//! CTR mode enables random-access decryption (any byte range without
  5→//! processing preceding bytes), required for streaming media playback.
  6→//!
  7→//! Uses Ctr64BE (big-endian 64-bit counter) to match Web Crypto API's
  8→//! `AES-CTR` with `length: 64`.
  9→//!
 10→//! SECURITY NOTE: AES-CTR does NOT provide authentication (unlike GCM).
 11→//! Integrity is provided by IPFS content addressing.
 12→
 13→use aes::Aes256;
 14→use ctr::cipher::{KeyIvInit, StreamCipher};
 15→use thiserror::Error;
 16→
 17→/// AES-CTR IV size in bytes (128-bit counter block).
 18→pub const AES_CTR_IV_SIZE: usize = 16;
 19→
 20→/// AES block size in bytes.
 21→const AES_BLOCK_SIZE: usize = 16;
 22→
 23→/// Type alias for AES-256-CTR with 64-bit big-endian counter.
 24→/// Matches Web Crypto API's `AES-CTR` with `length: 64`.
 25→type Aes256Ctr64BE = ctr::Ctr64BE<Aes256>;
 26→
 27→#[derive(Debug, Error)]
 28→pub enum AesCtrError {
 29→    #[error("Invalid key size")]
 30→    InvalidKeySize,
 31→    #[error("Invalid IV size")]
 32→    InvalidIvSize,
 33→    #[error("Encryption failed")]
 34→    EncryptionFailed,
 35→    #[error("Decryption failed")]
 36→    DecryptionFailed,
 37→    #[error("Invalid range")]
 38→    InvalidRange,
 39→}
 40→
 41→/// Encrypt data using AES-256-CTR.
 42→///
 43→/// Each encryption MUST use a unique IV (nonce + counter) with the same key.
 44→/// Reusing nonce+key pairs is catastrophic for AES-CTR security.
 45→///
 46→/// CTR output is the same size as the input (no authentication tag).
 47→pub fn encrypt_aes_ctr(
 48→    plaintext: &[u8],
 49→    key: &[u8; 32],
 50→    iv: &[u8; 16],
 51→) -> Result<Vec<u8>, AesCtrError> {
 52→    let mut cipher =
 53→        Aes256Ctr64BE::new(key.into(), iv.into());
 54→
 55→    let mut output = plaintext.to_vec();
 56→    cipher.apply_keystream(&mut output);
 57→
 58→    Ok(output)
 59→}
 60→
 61→/// Decrypt data encrypted with AES-256-CTR.
 62→///
 63→/// CTR encrypt == decrypt (XOR is symmetric), but provided as a separate
 64→/// function for API clarity.
 65→pub fn decrypt_aes_ctr(
 66→    ciphertext: &[u8],
 67→    key: &[u8; 32],
 68→    iv: &[u8; 16],
 69→) -> Result<Vec<u8>, AesCtrError> {
 70→    // CTR mode: decrypt is identical to encrypt
 71→    encrypt_aes_ctr(ciphertext, key, iv)
 72→}
 73→
 74→/// Decrypt an arbitrary byte range from AES-256-CTR encrypted data.
 75→///
 76→/// Computes the correct counter value for any byte offset and decrypts
 77→/// only the required blocks, avoiding the need to process the entire file.
 78→///
 79→/// The counter is computed as: baseCounter + floor(startByte / 16)
 80→/// where baseCounter is the initial counter value from the IV (bytes 8-15).
 81→///
 82→/// `ciphertext` must contain at least the block-aligned range covering
 83→/// `[start_byte, end_byte]` (inclusive).
 84→pub fn decrypt_aes_ctr_range(
 85→    ciphertext: &[u8],
 86→    key: &[u8; 32],
 87→    iv: &[u8; 16],
 88→    start_byte: usize,
 89→    end_byte: usize,
 90→) -> Result<Vec<u8>, AesCtrError> {
 91→    if start_byte > end_byte {
 92→        return Err(AesCtrError::InvalidRange);
 93→    }
 94→
 95→    if ciphertext.is_empty() || start_byte >= ciphertext.len() {
 96→        return Ok(Vec::new());
 97→    }
 98→
 99→    // Clamp end_byte to actual data
100→    let clamped_end = end_byte.min(ciphertext.len().saturating_sub(1));
101→    if clamped_end < start_byte {
102→        // Range is entirely beyond available data
103→        return Ok(Vec::new());
104→    }
105→
106→    // Compute block-aligned range
107→    let start_block = start_byte / AES_BLOCK_SIZE;
108→    let end_block = clamped_end / AES_BLOCK_SIZE;
109→    let block_aligned_start = start_block * AES_BLOCK_SIZE;
110→    let block_aligned_end = ((end_block + 1) * AES_BLOCK_SIZE).min(ciphertext.len());
111→
112→    // Build counter for starting block:
113→    // Copy nonce (first 8 bytes of IV), compute counter = baseCounter + startBlock
114→    let mut counter = [0u8; 16];
115→    counter[..8].copy_from_slice(&iv[..8]);
116→
117→    let base_counter = u64::from_be_bytes(iv[8..16].try_into().unwrap());
118→    let new_counter = base_counter.wrapping_add(start_block as u64);
119→    counter[8..16].copy_from_slice(&new_counter.to_be_bytes());
120→
121→    // Create cipher with adjusted counter
122→    let mut cipher = Aes256Ctr64BE::new(key.into(), &counter.into());
123→
124→    // Decrypt the block-aligned range
125→    let mut decrypted = ciphertext[block_aligned_start..block_aligned_end].to_vec();
126→    cipher.apply_keystream(&mut decrypted);
127→
128→    // Extract exact requested bytes from decrypted block-aligned data
129→    let offset_in_first_block = start_byte - block_aligned_start;
130→    let requested_length = clamped_end - start_byte + 1;
131→    let result = decrypted[offset_in_first_block..offset_in_first_block + requested_length].to_vec();
132→
133→    Ok(result)
134→}
