 1→//! Shared decrypt functions for folder and file metadata.
 2→//! Used by CipherBoxFS::drain_refresh_completions() which is platform-agnostic.
 3→
 4→/// Decrypt folder metadata from IPFS encrypted format.
 5→///
 6→/// Handles both v1 (JSON `{"iv":"...","data":"..."}`) and v2 blob
 7→/// (binary envelope with ECIES-wrapped key header). For v2 blobs,
 8→/// the key header is stripped and only the metadata JSON portion is decrypted.
 9→pub fn decrypt_metadata_from_ipfs_public(
10→    encrypted_bytes: &[u8],
11→    folder_key: &[u8],
12→) -> Result<crate::crypto::folder::FolderMetadata, String> {
13→    // Detect v1 vs v2 blob format
14→    let json_portion = if crate::crypto::vault_blob::detect_blob_version(encrypted_bytes) == 2 {
15→        // v2 blob: strip the key header, use only the metadata JSON portion
16→        let (_enc_key, metadata_json) =
17→            crate::crypto::vault_blob::deserialize_vault_blob_v2(encrypted_bytes)
18→                .map_err(|e| format!("Failed to parse v2 vault blob: {}", e))?;
19→        metadata_json
20→    } else {
21→        // v1: entire payload is JSON
22→        encrypted_bytes
23→    };
24→
25→    #[derive(serde::Deserialize)]
26→    struct EncryptedFolderMetadata {
27→        iv: String,
28→        data: String,
29→    }
30→
31→    let encrypted: EncryptedFolderMetadata = serde_json::from_slice(json_portion)
32→        .map_err(|e| format!("Failed to parse encrypted metadata JSON: {}", e))?;
33→
34→    let iv_bytes =
35→        hex::decode(&encrypted.iv).map_err(|_| "Invalid metadata IV hex".to_string())?;
36→    if iv_bytes.len() != 12 {
37→        return Err(format!(
38→            "Invalid IV length: {} (expected 12)",
39→            iv_bytes.len()
40→        ));
41→    }
42→    let iv: [u8; 12] = iv_bytes.try_into().unwrap();
43→
44→    use base64::Engine;
45→    let ciphertext = base64::engine::general_purpose::STANDARD
46→        .decode(&encrypted.data)
47→        .map_err(|e| format!("Invalid metadata base64: {}", e))?;
48→
49→    let folder_key_arr: [u8; 32] = folder_key
50→        .try_into()
51→        .map_err(|_| "Invalid folder key length".to_string())?;
52→
53→    // Reconstruct sealed format: IV || ciphertext (includes tag)
54→    let mut sealed = Vec::with_capacity(12 + ciphertext.len());
55→    sealed.extend_from_slice(&iv);
56→    sealed.extend_from_slice(&ciphertext);
57→
58→    crate::crypto::folder::decrypt_folder_metadata(&sealed, &folder_key_arr)
59→        .map_err(|e| format!("Metadata decryption failed: {}", e))
60→}
61→
62→/// Decrypt file metadata from IPFS encrypted JSON format.
63→pub fn decrypt_file_metadata_from_ipfs_public(
64→    encrypted_bytes: &[u8],
65→    folder_key: &[u8; 32],
66→) -> Result<crate::crypto::folder::FileMetadata, String> {
67→    #[derive(serde::Deserialize)]
68→    struct EncryptedFolderMetadata {
69→        iv: String,
70→        data: String,
71→    }
72→
73→    let encrypted: EncryptedFolderMetadata = serde_json::from_slice(encrypted_bytes)
74→        .map_err(|e| format!("Failed to parse encrypted file metadata JSON: {}", e))?;
75→
76→    let iv_bytes = hex::decode(&encrypted.iv)
77→        .map_err(|_| "Invalid file metadata IV hex".to_string())?;
78→    if iv_bytes.len() != 12 {
79→        return Err(format!(
80→            "Invalid IV length: {} (expected 12)",
81→            iv_bytes.len()
82→        ));
83→    }
84→    let iv: [u8; 12] = iv_bytes.try_into().unwrap();
85→
86→    use base64::Engine;
87→    let ciphertext = base64::engine::general_purpose::STANDARD
88→        .decode(&encrypted.data)
89→        .map_err(|e| format!("Invalid file metadata base64: {}", e))?;
90→
91→    // Reconstruct sealed format: IV || ciphertext (includes tag)
92→    let mut sealed = Vec::with_capacity(12 + ciphertext.len());
93→    sealed.extend_from_slice(&iv);
94→    sealed.extend_from_slice(&ciphertext);
95→
96→    crate::crypto::folder::decrypt_file_metadata(&sealed, folder_key)
97→        .map_err(|e| format!("File metadata decryption failed: {}", e))
98→}
