 92→/// Convert VersionEntry list to VersionCidEntry list for bin entries.
 93→/// Filters out entries with empty CIDs and returns None if the result is empty.
 94→pub fn versions_to_bin_entries(
 95→    versions: &Option<Vec<crate::crypto::folder::VersionEntry>>,
 96→) -> Option<Vec<crate::crypto::bin::VersionCidEntry>> {
 97→    versions.as_ref().and_then(|items| {
 98→        let mapped: Vec<crate::crypto::bin::VersionCidEntry> = items
 99→            .iter()
100→            .filter(|v| !v.cid.is_empty())
101→            .map(|v| crate::crypto::bin::VersionCidEntry {
102→                cid: v.cid.clone(),
103→                size: v.size,
104→            })
105→            .collect();
106→        if mapped.is_empty() { None } else { Some(mapped) }
107→    })
108→}
